    requires n >= 0
    ensures result == fib4_impl(n)
{
    var fib: array<int> := new int[n + 1];
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return 0;
    }
    if n == 2 {
        return 2;
    }
    if n == 3 {
        return 0;
    }
    fib[0] := 0;
    fib[1] := 0;
    fib[2] := 2;
    fib[3] := 0;
    var i: int;
    for i := 4 to n {
        fib[i] := fib[i - 1] + fib[i - 2] + fib[i - 3] + fib[i - 4];
    }
    return fib[n];
}

function fib4_impl(n: int): int
    requires n >= 0
    ensures (n == 0 ==> result == 0) &&
           (n == 1 ==> result == 0) &&
