{
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return 0;
    }
    if n == 2 {
        return 2;
    }
    if n == 3 {
        return 0;
    }
    return fib4_impl(n - 1) + fib4_impl(n - 2) + fib4_impl(n - 3) + fib4_impl(n - 4);
